def classify_existing_scans(apps, schema_editor):
    document_model = apps.get_model("netbox_oa", "MaintenanceDocument")
    sources = {}
    for document in (
        document_model.objects.using(schema_editor.connection.alias)
        .order_by("order_id", "material", "version")
        .iterator()
    ):
        key = (document.order_id, document.material)
        if document.state in {"paper", "sealed"}:
            document.kind = "scan"
            document.source_document_id = sources.get(key)
            document.save(
                update_fields=["kind", "source_document"], using=schema_editor.connection.alias
            )
        else:
            sources[key] = document.pk


